var n=`1278-oil-down`;var t=`world-1278`;var a=`GD`;var o=`central-america-caribbean`;var r=4;var s=1542;var l={en:`Oil Down`,ua:`Ойл даун`};var d={en:`Oil Down is a dish from Grenada featuring salt cod, yellow onion, garlic, pumpkin. This home-sized recipe records each ingredient at the step where it is used. Salt cod must be desalinated before coconut-breadfruit oil down.`,ua:`Ойл даун, страва кухні країни Гренада з такими основними складниками: солона тріска, жовта цибуля, часник, гарбуз. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Солону тріску потрібно вимочити перед приготуванням олійного рагу з кокосом і хлібним плодом.`};var g=[{en:`Soak salt cod in cold water in the refrigerator for about 24 hours, changing the water several times. Drain before simmering; never soak salted fish at room temperature.`,ua:`Вимочуйте солону тріску в холодній воді в холодильнику близько доби, кілька разів змінюючи воду. Злийте перед варінням; не вимочуйте рибу за кімнатної температури.`,t:[`soaking-dried-produce`],m:1440,i:[[`salt-cod`,320,`g`],[`water`,1500,`ml`]]},{en:`Gently cook the prepared contents in the simmering liquid from earlier steps until fully cooked and safe to eat.`,ua:`Обережно доведіть підготовлені продукти до повної готовності в гарячій рідині з попередніх етапів.`,t:[`poaching`],m:12,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,170,`g`],[`garlic`,5,`clove`],[`pumpkin`,310,`g`],[`coconut-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 75 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 75 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:75,i:[[`breadfruit`,650,`g`],[`plantain`,420,`g`],[`coconut-milk`,650,`ml`],[`thyme`,4,`sprig`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`chili-powder`,5,`g`],[`green-onion`,30,`g`]]}];var u={slug:n,id:t,country:`GD`,region:o,servings:4,minutes:s,title:l,text:d,steps:g};export{a as country,u as default,t as id,s as minutes,o as region,r as servings,n as slug,g as steps,d as text,l as title};